const data = $input.item.json;
const noticias = [];
const results = data.news_results || data.organic_results || [];
for (const r of results) {
  const titulo = r.title || '';
  const link = r.link || r.url || '';
  const fonte = r.source?.name || r.displayed_link || '';
  const data_pub = r.date || r.published_date || new Date().toISOString().slice(0,10);
  const resumo = (r.snippet || r.description || '').slice(0,300);
  if (!titulo || !link) continue;
  noticias.push({ titulo, link, fonte, data: data_pub, resumo });
}
return noticias.map(n => ({ json: n }));

