const r = $input.item.json;
const noticias = $('Preparar Prompt IA').item.json.noticias || [];
const hoje10 = new Date().toISOString().slice(0,10);
let classificados = [];
try {
  const raw = r.choices?.[0]?.message?.content || '';
  classificados = JSON.parse(raw.replace(/```json|```/g,'').trim());
} catch(e) {
  classificados = noticias.slice(0,8).map((n,i) => ({ idx: i+1, tema: n.titulo.slice(0,80), angle: n.resumo.slice(0,120), tipo: 'informativo', prioridade: 2, data_sugerida: hoje10 }));
}
const sugestoes = classificados
  .filter(c => c.idx >= 1 && c.idx <= noticias.length)
  .sort((a,b) => (a.prioridade||2) - (b.prioridade||2))
  .map(c => {
    const n = noticias[c.idx - 1];
    const id = 'sug_' + hoje10.replace(/-/g,'') + '_' + String(c.idx) + '_' + Math.random().toString(36).slice(2,6);
    return {
      id,
      tema: c.tema || n.titulo,
      angle: c.angle || '',
      tipo: c.tipo || 'informativo',
      prioridade: c.prioridade || 2,
      link: n.link,
      fonte: n.fonte,
      dataNoticia: n.data,
      dataSugestao: hoje10,
      dataPublicacao: c.data_sugerida || hoje10,
      origem: 'automatico',
      status: 'pendente'
    };
  });
return sugestoes.map(s => ({ json: s }));

